            loop = ["repeat", i, 0, len_, right.typ.count, loop_body]
            ret.append(
                [
                    "seq",
                    ["mstore", found_ptr, not_found],
                    loop,
                    ["mload", found_ptr],
                ]
            )
            return IRnode.from_list(b1.resolve(b2.resolve(ret)), typ="bool")
