PASSWORD_HASH_DUMMY_VALUE = 'DummyValue'
@unique
class PasswordHasherAvailability(Enum):
    LEGACY = 'legacy'
PASSWORD_HASHERS_ALL = {
    'CRYPT-PW': des_crypt,
    'MD5-PW': md5_crypt,
    'BCRYPT-PW': bcrypt,
}
def get_password_hashers(permit_legacy=True):
    """
    Get the enabled password hashers, and if permit_legacy is True, also legacy ones.
    Returned as a dict with keys being auth values, values being the hash functions.
    """
    hashers = {}
    included_availabilities = {PasswordHasherAvailability.ENABLED}
    if permit_legacy:
        included_availabilities.add(PasswordHasherAvailability.LEGACY)
    for hasher_name, hasher_function in PASSWORD_HASHERS_ALL.items():
        setting = get_setting(f'auth.password_hashers.{hasher_name.lower()}')
        availability = getattr(PasswordHasherAvailability, setting.upper())
        if availability in included_availabilities:
            hashers[hasher_name] = hasher_function
    return hashers
class RPSLMntner(RPSLObject):
    def clean(self):
        """Check whether either all hash values are dummy hashes, or none."""
        if not super().clean():
            return False
        dummy_matches = [auth[1] == PASSWORD_HASH_DUMMY_VALUE for auth in self._auth_lines(True)]
        if any(dummy_matches) and not all(dummy_matches):
            self.messages.error('Either all password auth hashes in a submitted mntner must be dummy objects, or none.')
    def verify_auth(self, passwords: List[str], keycert_obj_pk: Optional[str]=None) -> bool:
        """
        Verify whether one of a given list of passwords matches
        any of the auth hashes in this object, or match the
        keycert object PK.
        """
        hashers = get_password_hashers(permit_legacy=True)
        for auth in self.parsed_data.get('auth', []):
            if keycert_obj_pk and auth.upper() == keycert_obj_pk.upper():
                return True
            if ' ' not in auth:
                continue
            scheme, hash = auth.split(' ', 1)
            hasher = hashers.get(scheme.upper())
            if hasher:
                for password in passwords:
                    try:
                        if hasher.verify(password, hash):
                            return True
                    except ValueError:
                        pass
        return False
    def has_dummy_auth_value(self) -> bool:
        """
        Check whether this object has dummy auth hashes.
        If clean() has returned successfully before, the answer from this method
        means that either all or no hashes have dummy values.
        """
        auth_values = [auth[1] for auth in self._auth_lines(password_hashes=True)]
        return bool(auth_values) and all([value == PASSWORD_HASH_DUMMY_VALUE for value in auth_values])
class RPSLAuthField(RPSLTextField):
    def parse(self, value: str, messages: RPSLParserMessages, strict_validation=True) -> Optional[RPSLFieldParseResult]:
        hashers = get_password_hashers(permit_legacy=not strict_validation)
def whois_query(host: str, port: int, query: str, end_markings: List[str]=None) -> str:
    """
    Perform a query on a whois server, connecting to the specified host and port.
    Will continue to read until no more data can be read, until no more data has
    been sent for 5 seconds, or until an optional end_marking is encountered.
    The end marking could be e.g. 'END NTTCOM' in case of an NRTM stream.
    """
    query = query.strip() + '\n'
    logger.debug(f'Running whois query {query.strip()} on {host} port {port}')
    if end_markings:
        end_markings_bytes = [mark.encode('utf-8') for mark in end_markings]
    else:
        end_markings_bytes = []
    s = socket.create_connection((host, port), timeout=5)
    s.sendall(query.encode('utf-8'))
    buffer = b''
    while not any([end_marking in buffer for end_marking in end_markings_bytes]):
        try:
            data = s.recv(1024*1024)
        except socket.timeout:
            break
        if not data:
            break
        buffer += data
    s.close()
    return buffer.decode('utf-8', errors='backslashreplace')

class NotifyPlugin( pluginmanager.Plugin ):
