            else:
                raise BLPFormatError(f"Unknown BLP encoding {repr(self._blp_encoding)}")
        else:
            raise BLPFormatError(
                f"Unknown BLP compression {repr(self._blp_compression)}"
            )
        self.set_as_raw(bytes(data))

