                app.logger.error("Error: multiple entries with this login. "+ \
                          "Trying first entry...")
            uid = c.entries[0].entry_dn
        else:
            app.logger.error("Error: Login not found")
        c.unbind()
    return uid
def try_ldap_login(login, password):
    """ Connect to a LDAP directory to verify user login/passwords"""
    result = "Wrong login/password"
    s = Server(config.LDAPURI, port=config.LDAPPORT,
               use_ssl=False, get_info=ALL)
    uid = useruid(s, escape_filter_chars(login))
    if uid:
        c = Connection(s, user = uid , password = password, auto_bind = True)
        c.open()
        c.bind()
        result =  c.result["description"]
        c.unbind()
    return result
def try_login(login, password, method="LDAP"):
    if method == "LDAP":
        return try_ldap_login(login, password)
@app.route("/user/login", methods=["POST"])
def user_login():
    """Allow passhportd to handle login/passwords for users"""
    if request.method != "POST":
        return utils.response("ERROR: POST method is required ", 405)
    login = request.form["login"]
    password = request.form["password"]
    if not login or not password:
        return utils.response("ERROR: The login and password are required ", 417)
    elif login != escape_rdn(login):
        return utils.response("ERROR: Bad input", 417)
    result = try_login(login, password)
    if result == "success":
        app.logger.info("Authentication ok for {}".format(login))
        return utils.response("Authorized", 200)
    app.logger.warning("Authentication error for {} => ".format(login) + str(result))
    return utils.response("Refused: " + str(result), 200)

def snake_case(value: str) -> str:
    value = re.sub(r"([A-Z]{2,})([A-Z][a-z]|[ -_]|$)", lambda m: m.group(1).title() + m.group(2), value.strip())
    value = re.sub(r"(^|[ _-])([A-Z])", lambda m: m.group(1) + m.group(2).lower(), value)
    return stringcase.snakecase(value)
def pascal_case(value: str) -> str:
    return stringcase.pascalcase(value)

def _sanitize(value: str) -> str:
    return re.sub(r"[^\w _-]+", "", value)
def group_title(value: str) -> str:
    value = re.sub(r"([A-Z]{2,})([A-Z][a-z]|[ -_]|$)", lambda m: m.group(1).title() + m.group(2), value.strip())
    value = re.sub(r"(^|[ _-])([A-Z])", lambda m: m.group(1) + m.group(2).lower(), value)
    return value
def snake_case(value: str) -> str:
    return stringcase.snakecase(group_title(_sanitize(value)))
def pascal_case(value: str) -> str:
    return stringcase.pascalcase(_sanitize(value))
def kebab_case(value: str) -> str:
    return stringcase.spinalcase(group_title(_sanitize(value)))

class FormBuilder:
    def get_create_field_function(self, type):
        """
            Takes string of field type and returns a Django Form Field Instance.
            Assumes form field creation functions are in the format:
            'create_fieldtype_field'
        """
        create_field_function = getattr(self, 'create_%s_field' % type, None)
        if create_field_function:
            return create_field_function
        else:
            import inspect
            method_list = [
                f[0] for f in
                inspect.getmembers(self.__class__, inspect.isfunction)
                if f[0].startswith('create_') and f[0].endswith('_field')
            ]
            raise AttributeError(
                "Could not find function matching format \
                create_<fieldname>_field for type: " + type,
                "Must be one of: " + ", ".join(method_list)
            )
    @property
    def formfields(self):
        formfields = OrderedDict()
        for field in self.fields:
            options = self.get_field_options(field)
            create_field = self.get_create_field_function(field.field_type)
            formfields[field.clean_name] = create_field(field, options)
        return formfields
    def get_field_options(self, field):
        options = {}
        options['label'] = field.label
        options['help_text'] = field.help_text
        options['required'] = field.required
        options['initial'] = field.default_value
        return options

