            "seq",
            make_setter(buf, ir_node),
            ["set", "dyn_ofst", abi_encode(dst, buf, context, _bufsz, returns_len=True)],
        ]
    subtyp = ir_node.typ.value_type
    child_abi_t = subtyp.abi_type
    ret = ["seq"]
