class Container(IsolationProvider):
    def assert_field_type(self, val: Any, _type: object) -> None:
        if not type(val) == _type:
            raise ValueError("Status field has incorrect type")
    def parse_progress(self, document: Document, untrusted_line: str) -> None:
        """
        Parses a line returned by the container.
        """
        try:
            untrusted_status = json.loads(untrusted_line)
            text = untrusted_status["text"]
            self.assert_field_type(text, str)
            error = untrusted_status["error"]
            self.assert_field_type(error, bool)
            percentage = untrusted_status["percentage"]
            self.assert_field_type(percentage, int)
            self.print_progress(document, error, text, percentage)
        except Exception:
            line = replace_control_chars(untrusted_line)
            error_message = (
                f"Invalid JSON returned from container:\n\n\tUNTRUSTED> {line}"
            )
            self.print_progress_trusted(document, True, error_message, -1)
    def exec(
        self,
        document: Document,
        args: List[str],
    ) -> int:
        args_str = " ".join(shlex.quote(s) for s in args)
        log.info("> " + args_str)
        with subprocess.Popen(
            args,
            stdin=None,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            bufsize=1,
            universal_newlines=True,
            startupinfo=startupinfo,
        ) as p:
            if p.stdout is not None:
                for untrusted_line in p.stdout:
                    self.parse_progress(document, untrusted_line)
            p.communicate()
            return p.returncode
    def exec_container(
        self,
        document: Document,
        command: List[str],
        extra_args: List[str] = [],
    ) -> int:
        container_runtime = self.get_runtime()
        if self.get_runtime_name() == "podman":
            security_args = ["--security-opt", "no-new-privileges"]
            security_args += ["--userns", "keep-id"]
        else:
            security_args = ["--security-opt=no-new-privileges:true"]
        security_args += ["--cap-drop", "all"]
        user_args = ["-u", "dangerzone"]
        prevent_leakage_args = ["--rm"]
        args = (
            ["run", "--network", "none"]
            + user_args
            + security_args
            + prevent_leakage_args
            + extra_args
            + [self.CONTAINER_NAME]
            + command
        )
        args = [container_runtime] + args
        return self.exec(document, args)
    def _convert(
        self,
        document: Document,
        ocr_lang: Optional[str],
    ) -> bool:
        with tempfile.TemporaryDirectory(dir=get_tmp_dir()) as t:
            tmp_dir = pathlib.Path(t)
            unsafe_dir = tmp_dir / "unsafe"
            unsafe_dir.mkdir()
            pixel_dir = tmp_dir / "pixels"
            pixel_dir.mkdir()
            safe_dir = tmp_dir / "safe"
            safe_dir.mkdir()
            return self._convert_with_tmpdirs(
                document=document,
                unsafe_dir=unsafe_dir,
                pixel_dir=pixel_dir,
                safe_dir=safe_dir,
                ocr_lang=ocr_lang,
            )
    def _convert_with_tmpdirs(
        self,
        document: Document,
        unsafe_dir: pathlib.Path,
        pixel_dir: pathlib.Path,
        safe_dir: pathlib.Path,
        ocr_lang: Optional[str],
    ) -> bool:
        success = False
        if ocr_lang:
            ocr = "1"
        else:
            ocr = "0"
        copied_file = unsafe_dir / "input_file"
        shutil.copyfile(f"{document.input_filename}", copied_file)
        command = [
            "/usr/bin/python3",
            "-m",
            "dangerzone.conversion.doc_to_pixels",
        ]
        extra_args = [
            "-v",
            f"{copied_file}:/tmp/input_file:Z",
            "-v",
            f"{pixel_dir}:/tmp/dangerzone:Z",
            "-e",
            f"ENABLE_TIMEOUTS={self.enable_timeouts}",
        ]
        ret = self.exec_container(document, command, extra_args)
        if ret != 0:
            log.error("documents-to-pixels failed")
        else:
            command = [
                "/usr/bin/python3",
                "-m",
                "dangerzone.conversion.pixels_to_pdf",
            ]
            extra_args = [
                "-v",
                f"{pixel_dir}:/tmp/dangerzone:Z",
                "-v",
                f"{safe_dir}:/safezone:Z",
                "-e",
                f"OCR={ocr}",
                "-e",
                f"OCR_LANGUAGE={ocr_lang}",
                "-e",
                f"ENABLE_TIMEOUTS={self.enable_timeouts}",
            ]
            ret = self.exec_container(document, command, extra_args)
            if ret != 0:
                log.error("pixels-to-pdf failed")
            else:
                if os.path.exists(document.output_filename):
                    os.remove(document.output_filename)
                container_output_filename = os.path.join(
                    safe_dir, "safe-output-compressed.pdf"
                )
                shutil.move(container_output_filename, document.output_filename)
                success = True
        return success
def get_resource_path(filename: str) -> str:
    if getattr(sys, "dangerzone_dev", False):
        project_root = pathlib.Path(__file__).parent.parent
        prefix = project_root.joinpath("share")
    else:
        if platform.system() == "Darwin":
            bin_path = pathlib.Path(sys.executable)
            app_path = bin_path.parent.parent
            prefix = app_path.joinpath("Resources", "share")
        elif platform.system() == "Linux":
            prefix = pathlib.Path(sys.prefix).joinpath("share", "dangerzone")
        elif platform.system() == "Windows":
            exe_path = pathlib.Path(sys.executable)
            dz_install_path = exe_path.parent
            prefix = dz_install_path.joinpath("share")
        else:
            raise NotImplementedError(f"Unsupported system {platform.system()}")
    resource_path = prefix.joinpath(filename)
    return str(resource_path)
def get_version() -> str:
    try:
        with open(get_resource_path("version.txt")) as f:
            version = f.read().strip()
    except FileNotFoundError:
        version = "unknown"
    return version
def replace_control_chars(untrusted_str: str) -> str:
    """Remove control characters from string. Protects a terminal emulator
    from obcure control characters"""
    sanitized_str = ""
    for char in untrusted_str:
        sanitized_str += char if char in string.printable else "_"
    return sanitized_str
class IsolationProvider(ABC):
    def _print_progress(
        self, document: Document, error: bool, text: str, percentage: float
    ) -> None:
        s = Style.BRIGHT + Fore.YELLOW + f"[doc {document.id}] "
        s += Fore.CYAN + f"{percentage}% " + Style.RESET_ALL
        if error:
            s += Fore.RED + text + Style.RESET_ALL
            log.error(s)
        else:
            s += text
            log.info(s)
        if self.progress_callback:
            self.progress_callback(error, text, percentage)
    def print_progress_trusted(
        self, document: Document, error: bool, text: str, percentage: float
    ) -> None:
        return self._print_progress(document, error, text, percentage)
    def print_progress(
        self, document: Document, error: bool, untrusted_text: str, percentage: float
    ) -> None:
        text = replace_control_chars(untrusted_text)
        return self.print_progress_trusted(
            document, error, "UNTRUSTED> " + text, percentage
        )
