def start_retry_payment_intent_session(
    request: HttpRequest, user: UserProfile, stripe_payment_intent_id: str = REQ()
) -> HttpResponse:
    customer = get_customer_by_realm(user.realm)
    if customer is None:
        raise JsonableError(_("Please create a customer first."))
    try:
        payment_intent = PaymentIntent.objects.get(
            stripe_payment_intent_id=stripe_payment_intent_id, customer=customer
        )
    except PaymentIntent.DoesNotExist:
        raise JsonableError(_("Invalid payment intent id."))
    stripe_payment_intent = stripe.PaymentIntent.retrieve(stripe_payment_intent_id)
    if stripe_payment_intent.status == "succeeded":
        raise JsonableError(_("Payment already succeeded."))
    if (
        stripe_payment_intent.status == "processing"
    ):
        raise JsonableError(_("Payment processing."))
    metadata: Dict[str, Any] = {
        "user_id": user.id,
    }
    metadata.update(stripe_payment_intent.metadata)
    stripe_session = stripe.checkout.Session.create(
        cancel_url=f"{user.realm.uri}/upgrade/",
        customer=customer.stripe_customer_id,
        metadata=metadata,
        setup_intent_data={"metadata": metadata},
        mode="setup",
        payment_method_types=["card"],
        success_url=f"{user.realm.uri}/billing/event_status?stripe_session_id={{CHECKOUT_SESSION_ID}}",
    )
    session = Session.objects.create(
        stripe_session_id=stripe_session.id,
        customer=customer,
        type=Session.RETRY_UPGRADE_WITH_ANOTHER_PAYMENT_METHOD,
    )
    session.payment_intent = payment_intent
    session.save(update_fields=["payment_intent"])
    session.save()
    return json_success(
        request,
        data={
            "stripe_session_id": stripe_session.id,
            "stripe_session_url": stripe_session.url,
        },
    )
class Addressee:
    @staticmethod
    def legacy_build(
        sender: UserProfile,
        message_type_name: str,
        message_to: Union[Sequence[int], Sequence[str]],
        topic_name: Optional[str],
        realm: Optional[Realm] = None,
    ) -> "Addressee":
        if realm is None:
            realm = sender.realm
        if message_type_name == "stream":
            if len(message_to) > 1:
                raise JsonableError(_("Cannot send to multiple streams"))
            if message_to:
                stream_name_or_id = message_to[0]
            else:
                if sender.default_sending_stream:
                    stream_name_or_id = sender.default_sending_stream.id
                else:
                    raise JsonableError(_("Missing stream"))
            if topic_name is None:
                raise JsonableError(_("Missing topic"))
            if isinstance(stream_name_or_id, int):
                return Addressee.for_stream_id(stream_name_or_id, topic_name)
            return Addressee.for_stream_name(stream_name_or_id, topic_name)
        elif message_type_name == "private":
            if not message_to:
                raise JsonableError(_("Message must have recipients"))
            if isinstance(message_to[0], str):
                emails = cast(Sequence[str], message_to)
                return Addressee.for_private(emails, realm)
            elif isinstance(message_to[0], int):
                user_ids = cast(Sequence[int], message_to)
                return Addressee.for_user_ids(user_ids=user_ids, realm=realm)
        else:
            raise JsonableError(_("Invalid message type"))
