class HTMLReportWriter(ReportWriter):
    def _w_raw(self, content):
        self.output.append(mark_safe(content))
    def _w(self, content):
        self.output.append(format_data(content, format_money_values=True))
    def _w_tag(self, tag, content):
        self._w_raw("<%s>" % tag)
        self._w(content)
        self._w_raw("</%s>" % tag)
    def write_data_table(self, report, report_data, has_totals=True):
        self._w_raw('<table class="table table-striped table-bordered">')
        self._w_raw("<thead><tr>")
        for c in report.schema:
            self._w_tag("th", c["title"])
        self._w_raw("</tr></thead>")
        self._w_raw("<tbody>")
        for datum in report_data:
            datum = report.read_datum(datum)
            self._w_raw("<tr>")
            for d in datum:
                self._w_tag("td", d)
            self._w_raw("</tr>")
        if has_totals:
            self._w_raw("<tr>")
            for d in report.read_datum(report.get_totals(report_data)):
                self._w_tag("td", d)
            self._w_raw("</tr>")
        self._w_raw("</tbody></table>")
    def write_text(self, text):
        self._w(text)
def get_current_babel_locale(fallback="en-US-POSIX"):
    """
    Get a Babel locale based on the thread's locale context.
    :param fallback:
      Locale to fallback to; set to None to raise an exception instead.
    :return: Babel Locale
    :rtype: babel.Locale
    """
    locale = get_babel_locale(locale_string=translation.get_language())
    if not locale:
        if fallback:
            locale = get_babel_locale(fallback)
        if not locale:
            raise ValueError("Error! Failed to get the current babel locale (lang=%s)." % (translation.get_language(),))
    return locale
def get_locally_formatted_datetime(datetime):
