def format_money(amount, digits=None, widen=0, locale=None):
    """
    Format a Money object in the given locale.
    If neither digits or widen is passed, the preferred number of digits for
    the amount's currency is used.
    :param amount: The Money object to format
    :type amount: Money
    :param digits: How many digits to format the currency with.
    :type digits: int|None
    :param widen: How many digits to widen any existing decimal width with.
    :type widen: int|None
    :param locale: Locale object or locale identifier
    :type locale: Locale|str
    :return: Formatted string
    :rtype: str
    """
    if not locale:
        loc = get_current_babel_locale()
    else:
        loc = get_babel_locale(locale)
    if widen == 0 and digits is None:
        return format_currency(amount.value, amount.currency, locale=loc, currency_digits=True)
    pattern = loc.currency_formats["standard"].pattern
    if digits is not None:
        pattern = pattern.replace(".00", "." + (digits * "0"))
    if widen:
        pattern = pattern.replace(".00", ".00" + (widen * "0"))
    return format_currency(amount.value, amount.currency, pattern, loc, currency_digits=False)
def get_price_ranges(shop, min_price, max_price, range_step):
    if range_step == 0:
        return
    ranges = []
    min_price_value = format_money(shop.create_price(min_price))
    ranges.append(("-%s" % min_price, _("Under %(min_limit)s") % {"min_limit": min_price_value}))
    for range_min in range(min_price, max_price, range_step):
        range_min_price = format_money(shop.create_price(range_min))
        range_max = range_min + range_step
        if range_max < max_price:
            range_max_price = format_money(shop.create_price(range_max))
            ranges.append(
                (
                    "%s-%s" % (range_min, range_max),
                    _("%(min)s to %(max)s") % dict(min=range_min_price, max=range_max_price),
                )
            )
    max_price_value = format_money(shop.create_price(max_price))
    ranges.append(("%s-" % max_price, _("%(max_limit)s & Above") % {"max_limit": max_price_value}))
    return ranges
def encode_line(line):
    if line.base_unit_price.amount.value != 0:
        discount_percent = line.discount_amount.amount.value / (line.base_unit_price.amount.value * line.quantity)
    else:
        discount_percent = 0
    return {
        "sku": line.sku,
        "text": line.text,
        "quantity": format_decimal(line.quantity, locale=get_current_babel_locale()),
        "unitPrice": format_money(line.base_unit_price.amount),
        "discountedUnitPrice": format_money(line.discounted_unit_price.amount),
        "discountAmount": format_money(line.discount_amount.amount),
        "discountPercent": format_percent(discount_percent, 2),
        "taxlessTotal": format_money(line.taxless_price.amount),
        "taxPercentage": format_percent(line.tax_rate, 2),
        "taxfulTotal": format_money(line.taxful_price.amount),
    }
