ETREE_MODULES = [
    'lxml.etree',
    'xml.etree.cElementTree',
    'cElementTree',
    'xml.etree.ElementTree',
    'elementtree.ElementTree'
]
types = None
modules = {}
ET = None
def set_default_interface(etree):
    """
    Sets the default interface that PyAMF will use to deal with XML entities
    (both objects and blobs).
    """
    global types, ET, modules
    t = _get_etree_type(etree)
    _types = set(types or [])
    _types.update([t])
    types = tuple(_types)
    modules[t] = etree
    old, ET = ET, etree
    return old
def find_libs():
    """
    Run through L{ETREE_MODULES} and find C{ElementTree} implementations so
    that any type can be encoded.
    We work through the C implementations first, then the pure Python versions.
    The downside to this is that B{all} libraries will be imported but I{only}
    one is ever used. The libs are small (relatively) and the flexibility that
    this gives seems to outweigh the cost. Time will tell.
    """
    from pyamf.util import get_module
    types = []
    mapping = {}
    for mod in ETREE_MODULES:
        try:
            etree = get_module(mod)
        except ImportError:
            continue
        t = _get_etree_type(etree)
        types.append(t)
        mapping[t] = etree
    return tuple(types), mapping
def is_xml(obj):
    """
    Determines C{obj} is a valid XML type.
    If L{types} is not populated then L{find_libs} be called.
    """
    global types
    try:
        _bootstrap()
    except ImportError:
        return False
    return isinstance(obj, types)
def _get_type(e):
    """
    Returns the type associated with handling XML objects from this etree
    interface.
    """
    try:
        return e.__class__
    except AttributeError:
        return type(e)
def _get_etree_type(etree):
    """
    Returns the type associated with handling XML objects from this etree
    interface.
    """
    e = etree.fromstring('<foo/>')
    return _get_type(e)
def _bootstrap():
    global types, modules, ET
    if types is None:
        types, modules = find_libs()
    if ET is None:
        try:
            etree = modules[types[0]]
        except IndexError:
            _no_et()
        set_default_interface(etree)
def tostring(element, *args, **kwargs):
    """
    Helper func to provide easy access to the (possibly) moving target that is
    C{ET}.
    """
    global modules
    _bootstrap()
    t = _get_type(element)
    etree = modules.get(t, None)
    if not etree:
        raise RuntimeError(
            'Unable to find the etree implementation related to %r '
            '(type %r)' % (element, t)
        )
    return etree.tostring(element, *args, **kwargs)
def fromstring(*args, **kwargs):
    """
    Helper func to provide easy access to the (possibly) moving target that is
    C{ET}.
    """
    global ET
    _bootstrap()
    return ET.fromstring(*args, **kwargs)
_version = None
jython = sys.platform.startswith('java')
can_compile_extensions = not jython
def set_version(version):
    global _version
    _version = version
def get_version():
    v = ''
    prev = None
    for x in _version:
        if prev is not None:
            if isinstance(x, int):
                v += '.'
        prev = x
        v += str(x)
    return v.strip('.')
def get_install_requirements():
    """
    Returns a list of dependencies for PyAMF to function correctly on the
    target platform.
    """
    install_requires = []
    if sys.version_info < (2, 5):
        install_requires.extend(["elementtree>=1.2.6", "uuid>=1.30"])
    if 'dev' in get_version():
        if can_compile_extensions:
            install_requires.extend(['Cython>=0.13'])
    return install_requires
def write_version_py(filename='pyamf/_version.py'):
    """
    """
    if os.path.exists(filename):
        os.remove(filename)
    content = """\
from pyamf.versions import Version
version = Version(*%(version)r)
"""
    a = open(filename, 'wt')
    try:
        a.write(content % {'version': _version})
    finally:
        a.close()
def make_extension(mod_name, **extra_options):
    """
    Tries is best to return an Extension instance based on the mod_name
    """
    base_name = os.path.join(mod_name.replace('.', os.path.sep))
    if have_cython:
        for ext in ['.pyx', '.py']:
            source = base_name + ext
            if os.path.exists(source):
                return Extension(mod_name, [source], **extra_options)
        print('WARNING: Could not find Cython source for %r' % (mod_name,))
    else:
        source = base_name + '.c'
        if os.path.exists(source):
            return Extension(mod_name, [source], **extra_options)
        print('WARNING: Could not build extension for %r, no source found' % (
            mod_name,))
def get_extensions():
    """
    Return a list of Extension instances that can be compiled.
    """
    if not can_compile_extensions:
        print(80 * '*')
        print('WARNING:')
        print(
            '\tAn optional code optimization (C extension) could not be '
            'compiled.\n\n'
        )
        print('\tOptimizations for this package will not be available!\n\n')
        print('Compiling extensions is not supported on %r' % (sys.platform,))
        print(80 * '*')
        return []
    extensions = []
    for p in recursive_glob('.', '*.pyx'):
        mod_name = os.path.splitext(p)[0].replace(os.path.sep, '.')
        e = make_extension(mod_name)
        if e:
            extensions.append(e)
    return extensions
def get_trove_classifiers():
    """
    Return a list of trove classifiers that are setup dependent.
    """
    classifiers = []
    def dev_status():
        version = get_version()
        if 'dev' in version:
            return 'Development Status :: 2 - Pre-Alpha'
        elif 'alpha' in version:
            return 'Development Status :: 3 - Alpha'
        elif 'beta' in version:
            return 'Development Status :: 4 - Beta'
        else:
            return 'Development Status :: 5 - Production/Stable'
    return classifiers + [dev_status()]
def recursive_glob(path, pattern):
    matches = []
    for root, dirnames, filenames in os.walk(path):
        for filename in fnmatch.filter(filenames, pattern):
            matches.append(os.path.normpath(os.path.join(root, filename)))
    return matches
REFERENCE_BIT = 0x01
class Decoder(codec.Decoder):
    def readInteger(self, signed=True):
        """
        Reads and returns an integer from the stream.
        @type signed: C{bool}
        @see: U{Parsing integers on OSFlash
        <http://osflash.org/amf3/parsing_integers>} for the AMF3 integer data
        format.
        """
        return decode_int(self.stream, signed)
    def readObject(self):
        """
        Reads an object from the stream.
        @raise ReferenceError: Unknown reference found.
        @raise DecodeError: Unknown object encoding detected.
        """
        ref = self.readInteger(False)
        if ref & REFERENCE_BIT == 0:
            obj = self.context.getObject(ref >> 1)
            if obj is None:
                raise pyamf.ReferenceError(
                    'Unknown reference %d' % (ref >> 1,)
                )
            if self.use_proxies is True:
                obj = self.readProxy(obj)
            return obj
        ref >>= 1
        class_def = self._getClassDefinition(ref)
        alias = class_def.alias
        obj = alias.createInstance(codec=self)
        obj_attrs = dict()
        self.context.addObject(obj)
        if class_def.encoding in (
                ObjectEncoding.EXTERNAL,
                ObjectEncoding.PROXY):
            obj.__readamf__(DataInput(self))
            if self.use_proxies is True:
                obj = self.readProxy(obj)
            return obj
        elif class_def.encoding == ObjectEncoding.DYNAMIC:
            self._readStatic(class_def, obj_attrs)
            self._readDynamic(class_def, obj_attrs)
        elif class_def.encoding == ObjectEncoding.STATIC:
            self._readStatic(class_def, obj_attrs)
        else:
            raise pyamf.DecodeError("Unknown object encoding")
        alias.applyAttributes(obj, obj_attrs, codec=self)
        if self.use_proxies is True:
            obj = self.readProxy(obj)
        return obj
    def readXML(self):
        """
        Reads an xml object from the stream.
        @return: An etree interface compatible object
        @see: L{xml.set_default_interface}
        """
        ref = self.readInteger(False)
        if ref & REFERENCE_BIT == 0:
            return self.context.getObject(ref >> 1)
        xmlstring = self.stream.read(ref >> 1)
        x = xml.fromstring(xmlstring)
        self.context.addObject(x)
        return x
    def readXMLString(self):
        """
        Reads a string from the data stream and converts it into
        an XML Tree.
        @see: L{readXML}
        """
        return self.readXML()
class Encoder(codec.Encoder):
    def writeList(self, n, is_proxy=False):
        """
        Writes a C{tuple}, C{set} or C{list} to the stream.
        @type n: One of C{__builtin__.tuple}, C{__builtin__.set}
            or C{__builtin__.list}
        @param n: The C{list} data to be encoded to the AMF3 data stream.
        """
        if self.use_proxies and not is_proxy:
            self.writeProxy(n)
            return
        self.stream.write(TYPE_ARRAY)
        ref = self.context.getObjectReference(n)
        if ref != -1:
            self._writeInteger(ref << 1)
            return
        self.context.addObject(n)
        self._writeInteger((len(n) << 1) | REFERENCE_BIT)
        self.stream.write('\x01')
        [self.writeElement(x) for x in n]
    def writeObject(self, obj, is_proxy=False):
        """
        Writes an object to the stream.
        """
        if self.use_proxies and not is_proxy:
            self.writeProxy(obj)
            return
        self.stream.write(TYPE_OBJECT)
        ref = self.context.getObjectReference(obj)
        if ref != -1:
            self._writeInteger(ref << 1)
            return
        self.context.addObject(obj)
        kls = obj.__class__
        definition = self.context.getClass(kls)
        alias = None
        class_ref = False
        if definition:
            class_ref = True
            alias = definition.alias
        else:
            alias = self.context.getClassAlias(kls)
            definition = ClassDefinition(alias)
            self.context.addClass(definition, alias.klass)
        if class_ref:
            self.stream.write(definition.reference)
