log = Logger()
class SlskProtoThread(threading.Thread):
    @staticmethod
    def pack_network_message(msg_obj):
        try:
            return msg_obj.make_network_message()
        except Exception:
            from traceback import format_exc
            log.add(("Unable to pack message type %(msg_type)s. %(error)s"),
                    {'msg_type': msg_obj.__class__, 'error': format_exc()})
        return None
    def process_peer_output(self, msg_obj):
        if msg_obj.conn not in self._conns:
            log.add_conn("Can't send the message over the closed connection: %(type)s %(msg_obj)s", {
                'type': msg_obj.__class__,
                'msg_obj': vars(msg_obj)
            })
            return
        msg = self.pack_network_message(msg_obj)
        if msg is None:
            return
        conn_obj = self._conns[msg_obj.conn]
        conn_obj.obuf.extend(UINT_PACK(len(msg) + 4))
        conn_obj.obuf.extend(UINT_PACK(self.peercodes[msg_obj.__class__]))
        conn_obj.obuf.extend(msg)
        self.modify_connection_events(conn_obj, selectors.EVENT_READ | selectors.EVENT_WRITE)
    def process_distrib_input(self, conn, msg_buffer):
        """ We have a distributed network connection, parent has sent us
        something, this function retrieves messages
        from the msg_buffer, creates message objects and returns them
        and the rest of the msg_buffer.
        """
        msg_buffer_mem = memoryview(msg_buffer)
        buffer_len = len(msg_buffer_mem)
        idx = 0
        while buffer_len >= 5:
            msgsize = UINT_UNPACK(msg_buffer_mem[idx:idx + 4])[0]
            msgsize_total = msgsize + 4
            if msgsize_total > buffer_len or msgsize < 0:
                break
            msgtype = msg_buffer_mem[idx + 4]
            if msgtype in self.distribclasses:
                msg = self.unpack_network_message(
                    self.distribclasses[msgtype], msg_buffer_mem[idx + 5:idx + msgsize_total], msgsize - 1,
                    "distrib", conn)
                if msg is not None:
                    self._callback_msgs.append(msg)
            else:
                log.add("Distrib message type %(type)i size %(size)i contents %(msg_buffer)s unknown",
                        {'type': msgtype, 'size': msgsize - 1, 'msg_buffer': msg_buffer[idx + 5:idx + msgsize_total]})
                self._callback_msgs.append(ConnClose(conn.conn, conn.addr))
                self.close_connection(self._conns, conn)
                break
            idx += msgsize_total
            buffer_len -= msgsize_total
        conn.ibuf = msg_buffer[idx:]
class Transfers:
    def push_file(self, user, filename, size, path="", transfer=None, bitrate=None, length=None, locally_queued=False):
        if not self.core.logged_in:
            return
        real_path = self.core.shares.virtual2real(filename)
        size_attempt = self.get_file_size(real_path)
        if size_attempt > 0:
            size = size_attempt
        if transfer is None:
            transfer = Transfer(
                user=user, filename=filename, path=path,
                status="Queued", size=size, bitrate=bitrate,
                length=length
            )
            self._append_upload(user, filename, transfer)
        else:
            transfer.filename = filename
            transfer.size = size
            transfer.status = "Queued"
        log.add_transfer(
            "Initializing upload request for file %(file)s to user %(user)s", {
                'file': filename,
                'user': user
            }
        )
        self.core.watch_user(user)
        if self.user_logged_out(user):
            transfer.status = "User logged off"
        elif not locally_queued:
            transfer.req = self.core.get_new_token()
            transfer.status = "Getting status"
            self.transfer_request_times[transfer] = time.time()
            log.add_transfer("Requesting to upload file %(filename)s with transfer "
                             + "request %(request)s to user %(user)s", {
                                 "filename": filename,
                                 "request": transfer.req,
                                 "user": user
                             })
            self.core.send_message_to_peer(
                user, slskmessages.TransferRequest(None, 1, transfer.req, filename, size, real_path))
        if self.uploadsview:
            self.uploadsview.update(transfer)
    def download_finished(self, file, i):
        self.close_file(file, i)
        folder, basename = self.get_download_destination(i.user, i.filename, i.path)
        newname = self.get_renamed(os.path.join(folder, basename))
        try:
            if not os.access(folder, os.F_OK):
                os.makedirs(folder)
            import shutil
            shutil.move(file.name, newname)
        except (IOError, OSError) as inst:
            log.add(
                _("Couldn't move '%(tempfile)s' to '%(file)s': %(error)s"), {
                    'tempfile': "%s" % file.name,
                    'file': newname,
                    'error': inst
                }
            )
            self.download_folder_error(i, inst)
            if self.downloadsview:
                self.downloadsview.update(i)
            return
        i.status = "Finished"
        i.currentbytes = i.size
        i.speed = None
        i.timeleft = ""
        i.conn = None
        self.core.statistics.append_stat_value("completed_downloads", 1)
        self.file_downloaded_actions(i.user, newname)
        self.folder_downloaded_actions(i.user, i.path)
        if self.downloadsview:
            self.downloadsview.new_transfer_notification(finished=True)
            if not self.auto_clear_download(i):
                self.downloadsview.update(i)
        self.core.pluginhandler.download_finished_notification(i.user, i.filename, newname)
        self.save_transfers("downloads")
        log.add_download(
            _("Download finished: user %(user)s, file %(file)s"), {
                'user': i.user,
                'file': i.filename
            }
        )
    def upload_finished(self, i, file_handle=None):
        if i.speed is not None:
            self.upload_speed = i.speed
            self.queue.append(slskmessages.SendUploadSpeed(i.speed))
        self.close_file(file_handle, i)
        ip_address = None
        if i.conn is not None:
            try:
                ip_address = i.conn.getpeername()
            except OSError:
                pass
        i.status = "Finished"
        i.currentbytes = i.size
        i.speed = None
        i.timeleft = ""
        i.conn = None
        for j in self.uploads:
            if j.user == i.user:
                j.timequeued = i.lasttime
        log.add_upload(
            _("Upload finished: user %(user)s, IP address %(ip)s, file %(file)s"), {
                'user': i.user,
                'ip': ip_address,
                'file': i.filename
            }
        )
        self.core.statistics.append_stat_value("completed_uploads", 1)
        if not self.auto_clear_upload(i) and self.uploadsview:
            self.uploadsview.update(i)
        real_path = self.core.shares.virtual2real(i.filename)
        self.core.pluginhandler.upload_finished_notification(i.user, i.filename, real_path)
        self.save_transfers("uploads")
        self.check_upload_queue()
