        src_uri = url_for('.get_object_src_http', dataset=dataset, rel_path=rel_path)
    return '<object id={} src={} hyperfind.external-link={} />' \
        .format(
        quoteattr(url_for('.get_object_id', dataset=dataset, seq_no=seq_no)),
        quoteattr(src_uri),
        quoteattr(download_link))

