log = logging.getLogger("subiquitycore.utils")
async def arun_command(
    cmd: Sequence[str],
    *,
    stdout=subprocess.PIPE,
    stderr=subprocess.PIPE,
    encoding="utf-8",
    input=None,
    errors="replace",
    env=None,
    clean_locale=True,
    check=False,
    **kw,
) -> subprocess.CompletedProcess:
    if input is None:
        if "stdin" not in kw:
            kw["stdin"] = subprocess.DEVNULL
    else:
        kw["stdin"] = subprocess.PIPE
        input = input.encode(encoding)
    log.debug("arun_command called: %s", cmd)
    proc = await asyncio.create_subprocess_exec(
        *cmd,
        stdout=stdout,
        stderr=stderr,
        env=_clean_env(env, locale=clean_locale),
        **kw,
    )
    stdout, stderr = await proc.communicate(input=input)
    if encoding:
        if stdout is not None:
            stdout = stdout.decode(encoding)
        if stderr is not None:
            stderr = stderr.decode(encoding)
    log.debug("arun_command %s exited with code %s", cmd, proc.returncode)
    assert proc.returncode is not None
    if check and proc.returncode != 0:
        raise subprocess.CalledProcessError(proc.returncode, cmd, stdout, stderr)
    else:
        return subprocess.CompletedProcess(cmd, proc.returncode, stdout, stderr)
class ConfigureController(SubiquityController):
    async def __recommended_language_packs(self, lang, env) -> Optional[List[str]]:
        cp = await arun_command([clsCommand, "-d", data_dir, "-l", clsLang], env=envcp)
    async def _install_check_lang_support_packages(self, lang, env) -> bool:
        """Install recommended packages.
        lang is expected to be one single language/locale.
        """
        packages = await self.__recommended_language_packs(lang, env)
        aptCommand = "/usr/bin/apt"
        if packages is None:
            log.error("Failed to detect recommended language packs.")
            return False
        if not self.app.opts.dry_run:
            cp = await arun_command([aptCommand, "update"], env=env)
            if cp.returncode != 0:
                log.debug("Failed to update apt cache.\n%s", cp.stderr)
        if self.app.opts.dry_run:
            if len(packages) == 0:
                log.error("Packages list in dry-run should never be empty.")
                return False
            log.debug(
                "%s ignored for testing.", self.model.wslsetupoptions.wslsetupoptions
            )
            packs_dir = os.path.join(self.model.root, "var/cache/apt/archives/")
            os.makedirs(packs_dir, exist_ok=True)
            try:
                for package in packages:
                    lcp = await arun_command(
                        [aptCommand, "install", package, "--simulate"], env=env
                    )
                    archive = os.path.join(packs_dir, package + ".log")
                    with open(archive, "wt") as f:
                        if lcp.returncode == 0:
                            f.write(lcp.stdout)
                return True
            except IOError as e:
                log.error("Failed to write file.", e)
                return False
        if len(packages) == 0:
            log.info("No missing recommended packages. Nothing to do.")
            return True
        cmd = []
        opts = self.model.wslsetupoptions.wslsetupoptions
        if opts is None or opts.install_language_support_packages is True:
            cmd = [aptCommand, "install", "-y"]
        else:
            cmd = ["/usr/bin/apt-mark", "install"]
        cmd = cmd + packages
        acp = await arun_command(cmd, env=env)
        return acp.returncode == 0
class FilesystemController(SubiquityController, FilesystemManipulator):
    async def guided(
        self, choice: GuidedChoiceV2, reset_partition_only: bool = False
    ) -> None:
        self.model.dd_target = None
        if choice.capability == GuidedCapability.MANUAL:
            return
        self.model.guided_configuration = choice
        self.set_info_for_capability(choice.capability)
        disk = self.model._one(id=choice.target.disk_id)
        if self.is_core_boot_classic():
            if not self.app.opts.enhanced_secureboot:
                raise ValueError(
                    "Not using enhanced_secureboot: disabled on commandline"
                )
            assert isinstance(choice.target, GuidedStorageTargetReformat)
            self.use_tpm = choice.capability == GuidedCapability.CORE_BOOT_ENCRYPTED
            await self.guided_core_boot(disk)
            return
        gap = self.start_guided(choice.target, disk)
        if DeviceAction.TOGGLE_BOOT in DeviceAction.supported(disk):
            self.add_boot_disk(disk)
        gap = gap.within()
        if gap is None:
            raise Exception("failed to locate gap after adding boot")
        if choice.reset_partition:
            if self.app.opts.dry_run:
                reset_size = DRY_RUN_RESET_SIZE
            else:
                cp = await arun_command(["du", "-sb", "/cdrom"])
                reset_size = int(cp.stdout.strip().split()[0])
                reset_size = align_up(int(reset_size * 1.10), 256 * MiB)
            reset_gap, gap = gap.split(reset_size)
            self.model.reset_partition = self.create_partition(
                device=reset_gap.device,
                gap=reset_gap,
                spec={"fstype": "fat32"},
                flag="msftres",
            )
            self.reset_partition_only = reset_partition_only
            if reset_partition_only:
                for mount in self.model._all(type="mount"):
                    self.delete_mount(mount)
                self.model.target = self.app.base_model.target = None
                return
        if choice.capability.is_lvm():
            self.guided_lvm(gap, choice)
        elif choice.capability.is_zfs():
            self.guided_zfs(gap, choice)
        elif choice.capability == GuidedCapability.DIRECT:
