        'ReturnCode': rcode.to_text(query.response.rcode()),
        'ID': query.response.id,
        'AA': 'AA' in flag_list,
        'TC': 'TC' in flag_list,
        'RD': 'RD' in flag_list,
        'RA': 'RA' in flag_list,
        'AD': 'AD' in flag_list
    }
def is_valid_ip(ip):
    def is_valid_ipv4_address(address):
        try:
            socket.inet_pton(socket.AF_INET, address)
        except AttributeError:
            try:
                socket.inet_aton(address)
            except socket.error:
                return False
            return address.count('.') == 3
        except socket.error:
            return False
        return True
    def is_valid_ipv6_address(address):
        try:
            socket.inet_pton(socket.AF_INET6, address)
        except socket.error:
            return False
        return True
    return is_valid_ipv4_address(ip) or is_valid_ipv6_address(ip)

